import json
import csv

def get_cvss_score(cvss_dict):
    if not cvss_dict:
        return "N/A"
    # Prefer nvd, then ghsa, then others
    for source in ['nvd', 'ghsa', 'redhat']:
        if source in cvss_dict:
            score = cvss_dict[source].get('V3Score') or cvss_dict[source].get('V2Score')
            if score is not None:
                return score
    # If preferred sources not found, pick first available
    for source in cvss_dict:
        score = cvss_dict[source].get('V3Score') or cvss_dict[source].get('V2Score')
        if score is not None:
            return score
    return "N/A"

with open('audit_results.json', 'r') as f:
    data = json.load(f)

vulnerabilities = []
seen = set()

if 'Results' in data:
    for result in data['Results']:
        if 'Vulnerabilities' in result:
            for vuln in result['Vulnerabilities']:
                severity = vuln.get('Severity', 'UNKNOWN')
                if severity in ['HIGH', 'CRITICAL']:
                    package = vuln.get('PkgName', 'N/A')
                    version = vuln.get('InstalledVersion', 'N/A')
                    cve_id = vuln.get('VulnerabilityID', 'N/A')

                    # Deduplicate if same package, version, and CVE
                    key = (package, version, cve_id)
                    if key in seen:
                        continue
                    seen.add(key)

                    cvss_score = get_cvss_score(vuln.get('CVSS'))
                    fixed_version = vuln.get('FixedVersion', 'N/A')
                    title = vuln.get('Title', 'N/A')
                    url = vuln.get('PrimaryURL', 'N/A')

                    vulnerabilities.append({
                        'Package': package,
                        'Version': version,
                        'CVE_ID': cve_id,
                        'Severity': severity,
                        'CVSS_Score': cvss_score,
                        'Fixed_Version': fixed_version,
                        'Title': title,
                        'Url': url
                    })

with open('security_audit.csv', 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url'])
    writer.writeheader()
    writer.writerows(vulnerabilities)
